el(d:JSONObject):String{val c=d.optInt("code");val r=if(d.isNull("code_label"))"" else d.optString("code_label").trim();return r.takeUnless{it.isBlank()||it.equals("null",true)}?:c.toString()};private fun showLogin(){root.removeAllViews();root.addView(tv("GESTIONE FLOTTA",12f,false,true));root.addView(tv("Area Responsabile",32f,true,true));val c=card();val n=input("Nome responsabile");val p=input("PIN").apply{inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD};val m=tv("",14f,false,true);c.addView(n);c.addView(p);c.addView(button("Accedi"){Api.postJson("/manager-login",JSONObject().put("name",n.text.toString().trim()).put("pin",p.text.toString().trim())){x,r->runOnUiThread{if(x in 200..299){val o=JSONObject(r);manager=o.optString("name");managerToken=o.optString("token");showDashboard()}else m.text="Accesso non riuscito"}}});c.addView(m);root.addView(c)};private fun showDashboard(){root.removeAllViews();root.addView(tv("GESTIONE FLOTTA",12f,false,true));root.addView(tv("Dashboard",32f,true,true));root.addView(tv("Responsabile: $manager",14f,false));addNotifications();addDailyDashboard();addGlobalSearch();addOverview();loadDriverData();addVehicleCard();addActive();addDamageReports();addDeviceAndHabitual();addDevices();addHistory();addPhotoCompare();addPhotos();root.addView(button("Torna ad autista",false){finish()});root.addView(button("Esci dall'area responsabile",false){manager="";managerToken="";showLogin()})};private fun addNotifications(){val c=card();c.addView(tv("NOTIFICHE RESPONSABILE",11f,false,true));val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(out);root.addView(c);Api.get("/manager-notifications",managerToken){x,r->runOnUiThread{out.removeAllViews();if(x !in 200..299){out.addView(tv("Errore caricamento notifiche",14f,false));return@runOnUiThread};val o=JSONObject(r);val a=o.optJSONArray("items")?:JSONArray();if(a.length()==0){out.addView(tv("Nessuna notifica attiva",14f,false));return@runOnUiThrea