View(tv("SCHEDA COMPLETA AUTISTA",11f,false,true));val sp=Spinner(this);val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(sp);c.addView(button("Apri scheda autista"){if(drivers.length()==0)return@button;val d=drivers.getJSONObject(sp.selectedItemPosition);Api.get("/manager-driver-card?driver_code=${d.optInt("code")}",managerToken){x,r->runOnUiThread{out.removeAllViews();if(x !in 200..299){out.addView(tv("Autista non trovato",14f,false));return@runOnUiThread};val o=JSONObject(r);val dr=o.getJSONObject("driver");out.addView(tv("${dr.optString("name")} · ${label(dr)}",22f,true,true));out.addView(tv("Furgone abituale: ${dr.optString("habitual_plate").takeUnless{it.isBlank()||it.equals("null",true)}?:"Nessuno"}",15f));val cur=o.optJSONObject("current");out.addView(tv("Mezzo attuale: ${if(cur!=null)cur.optString("plate")+" · "+cur.optString("checkout_at") else "Nessun mezzo assegnato"}",15f));fun section(title:String,a:JSONArray,render:(JSONObject)->String){out.addView(tv(title,12f,false,true));if(a.length()==0)out.addView(tv("Nessun dato",14f,false));for(i in 0 until a.length())out.addView(tv(render(a.getJSONObject(i)),14f))};section("DISPOSITIVI",o.optJSONArray("devices")?:JSONArray()){z->"${z.optString("device_label","Dispositivo")}\nAssociato: ${z.optString("created_at")}"};section("SEGNALAZIONI",o.optJSONArray("reports")?:JSONArray()){z->"${z.optString("status").uppercase()} · ${z.optString("plate")} · ${z.optString("category")}\n${z.optString("description")}"};section("FOTO EFFETTUATE",o.optJSONArray("photos")?:JSONArray()){z->"${z.optString("plate")} · ${z.optString("photo_type")}\n${z.optString("created_at")}"};section("STORICO MEZZI UTILIZZATI",o.optJSONArray("history")?:JSONArray()){z->"${z.optString("plate")}${if(!z.isNull("checkout_km"))" · ${z.optInt("checkout_km")} km" else ""}\nRitiro: ${z.optString("checkout_at")}\nRientro: ${z.optString("return_at").takeUnless{it.isBlank()||it.equals("null",true)}?:"IN CORSO"}"}}}});c.addView(o