s.getJSONObject(vs.selectedItemPosition-1).optString("plate");Api.postJson("/manager-habitual",JSONObject().put("driver_code",d.optInt("code")).put("plate",p),managerToken){x,_->runOnUiThread{f.text=if(x in 200..299)"Furgone abituale aggiornato" else "Errore"}}}});c.addView(f);root.addView(c)};private fun addDevices(){val c=card();c.addView(tv("DISPOSITIVI ASSOCIATI",11f,false,true));root.addView(c);Api.get("/manager-devices",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONArray(r);for(i in 0 until a.length()){val z=a.getJSONObject(i);c.addView(tv("${z.optString("name")} · ${z.optString("device_label")}",14f))}}}}};private fun addHistory(){val c=card();c.addView(tv("STORICO RITIRI E RESTITUZIONI",11f,false,true));val p=input("Targa (facoltativa)");val out=tv("",14f,false);c.addView(p);c.addView(button("Cerca storico",false){Api.get("/manager-history?plate=${URLEncoder.encode(p.text.toString().trim().uppercase(),"UTF-8")}",managerToken){x,r->runOnUiThread{if(x in 200..299){val a=JSONArray(r);out.text=(0 until a.length()).joinToString("\n\n"){i->val z=a.getJSONObject(i);"${z.optString("plate")} · ${z.optString("name")}\n${z.optString("checkout_at")} → ${z.optString("return_at")}"}}}}});c.addView(out);root.addView(c)};private fun addPhotoCompare(){val c=card();c.addView(tv("CONFRONTO FOTOGRAFICO",11f,false,true));val p=input("Targa");val out=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};c.addView(p);c.addView(button("Confronta foto",false){val plate=p.text.toString().trim().uppercase();if(plate.isBlank())return@button;Api.get("/manager-photos?plate=${URLEncoder.encode(plate,"UTF-8")}",managerToken){x,r->runOnUiThread{out.removeAllViews();if(x !in 200..299){out.addView(tv("Errore caricamento foto",14f,false));return@runOnUiThread};val a=JSONArray(r);val groups=linkedMapOf<String,MutableList<JSONObject>>();for(i in 0 until a.length()){val z=a.getJSONObject(i);val key=z.optString("assignment_id").takeUnless{it.isBlank()||it.equals("null",true)}?:"day-"+z.optString("created_at").take(10);groups.getOrPut(key){mutableListOf()}.add(z)};val g=groups.values.toList();if(g.size<2){out.addView(tv("Servono almeno due sessioni fotografiche per il confronto",14f,false));return@runOnUiThread};out.addView(tv("$plate · PRIMA / DOPO",18f,true,true));val before=g[1];val after=g[0];val types=(before+after).map{it.optString("photo_type","Foto mezzo")}.distinct();for(t in types){out.addView(tv(t,12f,false,true));val b=before.find{it.optString("photo_type","Foto mezzo")==t};val a2=after.find{it.optString("photo_type","Foto mezzo")==t};out.addView(tv("PRIMA: ${b?.optString("created_at")?:"Foto assente"}\nDOPO: ${a2?.optString("created_at")?:"Foto assente"}",14f));if(b!=null)out.addView(button("Apri foto PRIMA",false){startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(b.optString("photo_url"))) )});if(a2!=null)out.addView(button("Apri foto DOPO",false){startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(a2.optString("photo_url"))) )})}}}});c.addView(out);root.addView(c)};private fun addPhotos(){val c=card();c.addView(tv("FOTO MEZZI",11f,false,true));val p=input("Targa (facoltativa)");c.addView(p);c.addView(button("Cerca foto",false){Api.get("/manager-photos?plate=${URLEncoder.encode(p.text.toString().trim().uppercase(),"UTF-8")}",managerToken){_,_->}});root.addView(c)}}